import shlex,time,urllib.request,urllib.error

def v0_get(path):
 try:
  with urllib.request.urlopen('http://127.0.0.1:3000'+path,timeout=5) as response:return {'status':response.status,'body':json.loads(response.read())}
 except urllib.error.HTTPError as error:return {'status':error.code,'body':json.loads(error.read())}

def v0_a4_counts():
 names=['agent_runs','approvals','conversation_idempotency','conversations','messages','run_attempts','run_checkpoints','tasks','task_events','outbox','notifications']
 return v0_readonly_sql('SELECT '+','.join('(SELECT count(*)::int FROM '+name+') AS '+name for name in names))[0]

def v0_apply_resource_fault(label,mutation=None,version='fixture-v1'):
 command=['bun','--preload','/evidence/observer.mjs','apps/api/dist/main.js']
 if mutation:command=['sh','-c','bun --eval '+shlex.quote(mutation)+' && exec bun --preload /evidence/observer.mjs apps/api/dist/main.js']
 override={'services':{'api':{'environment':{'ROLE':'all','V0_INSTANCE':label,'TZDB_VERSION':version},'command':command}}}
 path=v0_accept_root/('compose-'+label+'.json')
 write(str(path),json.dumps(override,indent=2))
 result=subprocess.run(v0_compose_args+['-f',str(path),'up','--detach','--no-deps','--force-recreate','api'],cwd=v0_a2_tree,env={**v0_accept_env,'DB_PORT':'55440'},capture_output=True,text=True,timeout=90)
 if result.returncode:raise RuntimeError('Owned Compose resource-fault recreation failed: '+result.stderr)
 deadline=time.monotonic()+25
 while True:
  try:
   if v0_get('/healthz')['status']==200:break
  except (OSError,ValueError):pass
  if time.monotonic()>deadline:raise RuntimeError('Owned fault API did not become live')
  time.sleep(0.2)
 info=json.loads(subprocess.check_output(['docker','inspect','along-v0-accept-api-1'],text=True))[0]
 assert info['Image']=='sha256:2f2ae03e81180222023a4d897205af4569b2556008b78b72036d321bd248f627'
 probe="""import{createHash}from'node:crypto';import{existsSync,readFileSync}from'node:fs';const result={declaredVersion:process.env.TZDB_VERSION};for(const[name,file]of[['rules','fixture-v1.json'],['aliases','aliases-v1.json']]){const path='/app/apps/api/resources/time/'+file;if(!existsSync(path)){result[name]={exists:false};continue;}const text=readFileSync(path,'utf8');let parsed;try{parsed=JSON.parse(text);}catch{}result[name]={exists:true,bytes:Buffer.byteLength(text),sha256:createHash('sha256').update(text).digest('hex'),validJson:parsed!==undefined,...(name==='rules'&&parsed?{ruleset_id:parsed.ruleset_id,tzdb_version:parsed.tzdb_version}:{})};}console.log(JSON.stringify(result));"""
 p=subprocess.run(['docker','exec','along-v0-accept-api-1','bun','--eval',probe],capture_output=True,text=True,encoding='utf-8',timeout=15);assert p.returncode==0
 return {'label':label,'started_at':info['State']['StartedAt'],'image_id':info['Image'],'role':'all','actual_resource_probe':json.loads(p.stdout),'readyz':v0_get('/readyz'),'healthz':v0_get('/healthz')}

