def v0_readonly_sql(sql,params=None):
 script="""import {createPool} from './apps/api/src/db/pool.ts';const pool=createPool();const client=await pool.connect();try{await client.query('BEGIN READ ONLY');const result=await client.query(process.env.V0_QUERY,JSON.parse(process.env.V0_PARAMS));console.log(JSON.stringify(result.rows));await client.query('ROLLBACK');}finally{client.release();await pool.end();}"""
 result=subprocess.run([v0_bun,'--eval',script],cwd=v0_a2_tree,env={**os.environ,'DATABASE_URL':v0_local_database,'V0_QUERY':sql,'V0_PARAMS':json.dumps(params or [])},capture_output=True,text=True,encoding='utf-8',timeout=30)
 if result.returncode:raise RuntimeError(result.stderr)
 return json.loads(result.stdout)

