import { channel } from 'node:diagnostics_channel';
import { openSync, writeSync, fsyncSync } from 'node:fs';
import { createRequire } from 'node:module';

const fd = openSync('/evidence/events.jsonl', 'a');
const instance = process.env.V0_INSTANCE ?? 'unlabelled';
function record(stage, detail = {}) {
  writeSync(fd, JSON.stringify({ at: new Date().toISOString(), instance, pid: process.pid, stage, ...detail }) + '\n');
  fsyncSync(fd);
}
record('preload_loaded', { role: process.env.ROLE });
for (const [name, fallbackStage] of [
  ['along.notifications.provider-call', 'provider_call_entered'],
  ['along.notifications.received', 'receive_committed'],
  ['along.scheduler.delivery-checkpoint', 'delivery_checkpoint'],
  ['along.scheduler.tick', 'worker_tick'],
]) {
  channel(name).subscribe((message) => {
    const stage = typeof message.stage === 'string' ? message.stage : fallbackStage;
    const detail = {};
    for (const key of ['taskId', 'notificationId', 'workerId', 'success']) {
      if (message[key] !== undefined) detail[key] = message[key];
    }
    record(stage, detail);
    if (process.env.V0_FAULT_TASK && message.taskId === process.env.V0_FAULT_TASK && stage === process.env.V0_FAULT_STAGE) {
      record('fault_paused', { taskId: message.taskId, checkpoint: stage });
      Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0);
    }
  });
}
process.on('exit', (code) => record('process_exit', { code }));

// Observe the real claim COMMIT acknowledgment; no SQL or result is replaced.
if (process.env.V0_FAULT_STAGE === 'claim_committed') {
  const { Client } = createRequire('/app/apps/api/dist/main.js')('pg');
  const query = Client.prototype.query;
  const armed = new WeakSet();
  Client.prototype.query = function (...args) {
    const text = typeof args[0] === 'string' ? args[0] : args[0]?.text ?? '';
    const values = args[1] ?? args[0]?.values;
    if (text.includes('INSERT INTO outbox') && values?.[2] === process.env.V0_FAULT_TASK && JSON.parse(values[4]).kind === 'send') {
      armed.add(this);
    }
    const committed = text.trim().toUpperCase() === 'COMMIT' && armed.has(this);
    if (text.trim().toUpperCase() === 'ROLLBACK' || committed) armed.delete(this);
    const result = Reflect.apply(query, this, args);
    if (!committed) return result;
    return result.then((value) => {
      record('claim_committed', { taskId: process.env.V0_FAULT_TASK });
      record('fault_paused', { taskId: process.env.V0_FAULT_TASK, checkpoint: 'claim_committed' });
      Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0);
      return value;
    });
  };
}

